// WF-09: A mentor approves / rejects / requests correction on an employee's weekly report.
// Body: { mentor_email, employee_email, action: APPROVE|REJECT|REQUEST_CORRECTION, iso_week? }
const b = $json.body || $json;
const mentor = String(b.mentor_email || '').toLowerCase().trim();
const employee = String(b.employee_email || '').toLowerCase().trim();
let action = String(b.action || 'APPROVE').toUpperCase().trim();
const week = (b.iso_week === undefined || b.iso_week === null || b.iso_week === '') ? null : parseInt(b.iso_week, 10);

const statusMap = { APPROVE: 'APPROVED', REJECT: 'REJECTED', REQUEST_CORRECTION: 'CORRECTION_REQUIRED' };
if (!statusMap[action]) action = 'APPROVE';
const newStatus = statusMap[action];

let sql, params;
if (!mentor || !employee) {
  sql = `SELECT 'BAD_INPUT' AS err`;
  params = [];
} else {
  // Only the employee's assigned mentor may act; only on non-final reports.
  sql = `WITH m AS (SELECT user_id FROM users WHERE email=$1 AND role='MENTOR'),
     e AS (SELECT user_id, mentor_id FROM users WHERE email=$2)
UPDATE weekly_reports w
SET status=$4,
    approved_by = CASE WHEN $4='APPROVED' THEN (SELECT user_id FROM m) ELSE NULL END,
    approved_at = CASE WHEN $4='APPROVED' THEN now() ELSE NULL END
FROM e, m
WHERE w.user_id = e.user_id
  AND e.mentor_id = m.user_id
  AND w.iso_year = EXTRACT(ISOYEAR FROM CURRENT_DATE)::int
  AND w.iso_week = COALESCE($3::int, EXTRACT(WEEK FROM CURRENT_DATE)::int)
  AND w.status IN ('SUBMITTED','UNDER_REVIEW','CORRECTION_REQUIRED')
RETURNING w.iso_week, w.status`;
  params = [mentor, employee, week, newStatus];
}
return [{ json: { action, mentor, employee, sql, params } }];

const action = $('Build Action').first().json.action;
const employee = $('Build Action').first().json.employee;
const d = $json || {};
let reply;
if (d.err === 'BAD_INPUT') {
  reply = '\u26a0\ufe0f mentor_email and employee_email are both required.';
} else if (!d.status) {
  reply = `\u26a0\ufe0f No matching submitted report for ${employee} (check the mentor is assigned and the week was submitted).`;
} else if (d.status === 'APPROVED') {
  reply = `\u2705 Week ${d.iso_week} report for ${employee} APPROVED and locked.`;
} else if (d.status === 'REJECTED') {
  reply = `\u274c Week ${d.iso_week} report for ${employee} rejected.`;
} else {
  reply = `\u270f\ufe0f Correction requested on week ${d.iso_week} report for ${employee}.`;
}
return [{ json: { reply, action, status: d.status || null } }];
